    for i in range(H):
        for j in range(W):
            if I[i][j]!=bg and (i,j) not in seen:
                q=[(i,j)]; seen.add((i,j)); comp={(i,j)}
                while q:
                    a,b=q.pop()
                    for da in(-1,0,1):
                        for db in(-1,0,1):
