import itertools
def cluster(pts,d):
    pts=set(pts); cl=[]
    while pts:
        p=next(iter(pts)); seen={(p)}
        stack=[p]; cs=[p]
        while stack:
            a,b=stack.pop()
            for da in(-d,d):
                for db in(-d,d):
                    q=(a+da,b+db)
                    if q in pts: seen.add(q); stack.append(q); cs.append(q)
        pts-=seen; cl.append(sorted(cs))
    return cl
