                    a,b=st.pop()
                    if (a,b) in comp: continue
                    comp.add((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        na,nb=a+da,b+db
                        if 0<=na<H and 0<=nb<W and g[na][nb]!=bgv and (na,nb) not in comp:
                            st.append((na,nb))
                seen|=(set(comp)|{c for c in [(p,q)]})
                comps.append(comp)
    return comps
