def comps_g(gi,bgv):
    H,W=len(gi),len(gi[0]); seen=set(); out=[]
    for p in range(H):
        for q in range(W):
            if gi[p][q]==bgv: continue
            st=[(p,q)]; comp=[]; seen.add((p,q))
            while st:
                a,b=st.pop(); comp.append((a,b,gi[a][b]))
                for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                    x,y=a+da,b+db
                    if 0<=x<H and 0<=y<W and (x,y) not in seen and gi[x][y]!=bgv:
                        seen.add((x,y)); st.append((x,y))
            out.append(comp)
    return out
